INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01NURDT0100000000000000000', '*', '', 'nu_progress_book', 'Carnet de suivi trimestriel (maternelle)', 'other', 'P', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","section_label","period_label","synthesis","domains_text","observations_text"]', '2026-10-23T13:02:00+01:00', '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT01F0000000000000000', '*', '', 'nu_progress_book', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Carnet de suivi</h2><p>Enfant : <strong>{{holder_name}}</strong>. Section : {{section_label}}. Période : {{period_label}}. Année scolaire : {{academic_year}}.</p><h3>Synthèse</h3><p style="white-space:pre-line">{{synthesis}}</p><h3>Par domaine</h3><p style="white-space:pre-line">{{domains_text}}</p><h3>Observations</h3><p style="white-space:pre-line">{{observations_text}}</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT01E0000000000000000', '*', '', 'nu_progress_book', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Progress book</h2><p>Child: <strong>{{holder_name}}</strong>. Section: {{section_label}}. Term: {{period_label}}. School year: {{academic_year}}.</p><h3>Summary</h3><p style="white-space:pre-line">{{synthesis}}</p><h3>By area</h3><p style="white-space:pre-line">{{domains_text}}</p><h3>Observations</h3><p style="white-space:pre-line">{{observations_text}}</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p><div>{{qr}}</div><p>Verification: {{verification_url}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01NURDT0200000000000000000', '*', '', 'nu_liaison_sheet', 'Fiche de liaison maternelle-primaire', 'other', 'L', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","section_label","path_summary","strengths","needs","destination"]', '2026-10-23T13:02:00+01:00', '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT02F0000000000000000', '*', '', 'nu_liaison_sheet', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Fiche de liaison vers l’école primaire</h2><p>Enfant : <strong>{{holder_name}}</strong>. Section : {{section_label}}. Année scolaire : {{academic_year}}. Destination : {{destination}}.</p><h3>Parcours</h3><p style="white-space:pre-line">{{path_summary}}</p><h3>Points d’appui</h3><p style="white-space:pre-line">{{strengths}}</p><h3>Besoins</h3><p style="white-space:pre-line">{{needs}}</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT02E0000000000000000', '*', '', 'nu_liaison_sheet', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Transition sheet to primary school</h2><p>Child: <strong>{{holder_name}}</strong>. Section: {{section_label}}. School year: {{academic_year}}. Destination: {{destination}}.</p><h3>Path</h3><p style="white-space:pre-line">{{path_summary}}</p><h3>Strengths</h3><p style="white-space:pre-line">{{strengths}}</p><h3>Needs</h3><p style="white-space:pre-line">{{needs}}</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p><div>{{qr}}</div><p>Verification: {{verification_url}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01NURDT0300000000000000000', '*', '', 'nu_pickup_card', 'Carte de personne autorisée à récupérer l’enfant', 'other', 'K', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["section_label","person_name","relationship","grant_label"]', '2026-10-23T13:02:00+01:00', '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT03F0000000000000000', '*', '', 'nu_pickup_card', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Carte de personne autorisée</h2><p><strong>{{person_name}}</strong> ({{relationship}}) est autorisé(e) à récupérer <strong>{{holder_name}}</strong>, section {{section_label}}. Validité : {{grant_label}}.</p><p>La carte ne suffit pas : l’agent vérifie le visage et la liste du jour. Elle est révoquée avec l’autorisation.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT03E0000000000000000', '*', '', 'nu_pickup_card', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Authorised pick-up card</h2><p><strong>{{person_name}}</strong> ({{relationship}}) is authorised to pick up <strong>{{holder_name}}</strong>, section {{section_label}}. Validity: {{grant_label}}.</p><p>The card is not enough: staff check the face and the list of the day. It is revoked with the authorisation.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p><div>{{qr}}</div><p>Verification: {{verification_url}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01NURDT0400000000000000000', '*', '', 'nu_exit_register', 'Registre des arrivées et sorties (maternelle)', 'other', 'R', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["register_date","sections_text","totals_text","rows_text"]', '2026-10-23T13:02:00+01:00', '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT04F0000000000000000', '*', '', 'nu_exit_register', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Registre des arrivées et sorties du {{register_date}}</h2><p>Sections : {{sections_text}}.</p><p>{{totals_text}}</p><p style="white-space:pre-line">{{rows_text}}</p><p>Édité le {{issued_on}} par {{holder_name}}. Numéro : {{number}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01NURDT04E0000000000000000', '*', '', 'nu_exit_register', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Arrival and departure register of {{register_date}}</h2><p>Sections: {{sections_text}}.</p><p>{{totals_text}}</p><p style="white-space:pre-line">{{rows_text}}</p><p>Printed on {{issued_on}} by {{holder_name}}. Number: {{number}}</p></body></html>', 1, '2026-10-23T13:02:00+01:00', NULL, '2026-10-23T13:02:00+01:00')
